import { citypeSave } from "@/api/system/ciModel";
import { Message } from 'element-ui';
export default {
  props: ['isShow'],
  data: function data() {
    return {
      submitForm: {
        name: '',
        isMenu: 0,
        isShowInTopo: 0
      },
      rules: {
        name: [{
          required: true,
          pattern: '[^ \x22]+',
          message: '名称不能为空',
          trigger: 'blur'
        }]
      }
    };
  },
  mounted: function mounted() {},
  methods: {
    save: function save() {
      var _this = this;
      // console.log(this.submitForm)
      this.$refs.submitForm.validate(function (valid) {
        if (valid) {
          _this.savaLoading = true;
          citypeSave(_this.submitForm).then(function (res) {
            Message({
              type: 'success',
              message: '保存成功！'
            });
            _this.$emit('saveCitype');
            _this.savaLoading = false;
          }).catch(function () {
            _this.savaLoading = false;
          });
        }
      });
    }
  }
};
